// v9.99: languages carry a world, the same as creature presets (v8.37) and
// weapons (v9.97). A Burrows & Badgers table should not scroll past Infernal to
// find Ravenspeak, and an SRD table should not be offered Hammings at all.
const LANGUAGE_CATALOG = [
  // --- D&D (SRD) ---
  { name: 'Common', world: 'dnd' }, { name: 'Dwarvish', world: 'dnd' },
  { name: 'Elvish', world: 'dnd' }, { name: 'Giant', world: 'dnd' },
  { name: 'Gnomish', world: 'dnd' }, { name: 'Goblin', world: 'dnd' },
  { name: 'Halfling', world: 'dnd' }, { name: 'Orc', world: 'dnd' },
  { name: 'Abyssal', world: 'dnd' }, { name: 'Celestial', world: 'dnd' },
  { name: 'Draconic', world: 'dnd' }, { name: 'Deep Speech', world: 'dnd' },
  { name: 'Infernal', world: 'dnd' }, { name: 'Primordial', world: 'dnd' },
  { name: 'Sylvan', world: 'dnd' }, { name: 'Undercommon', world: 'dnd' },
  // --- Burrows & Badgers ---
  { name: 'High Grovish', world: 'bnb' }, { name: 'Low Grovish', world: 'bnb' },
  { name: 'Hammings', world: 'bnb' }, { name: 'Dentrivis', world: 'bnb' },
  { name: 'Weaslie', world: 'bnb' }, { name: 'Omor', world: 'bnb' },
  { name: 'Mhinning', world: 'bnb' }, { name: 'Unney', world: 'bnb' },
  { name: 'Alper', world: 'bnb' }, { name: 'Psalmic', world: 'bnb' },
  { name: 'Dalmic', world: 'bnb' }, { name: 'Slannic', world: 'bnb' },
  { name: 'Laagspraak', world: 'bnb' }, { name: 'Ravenspeak', world: 'bnb' },
  { name: 'Mylium', world: 'bnb' },
];
// Every known language name, both worlds. This is what "is it homebrew?" is
// tested against: a B&B language is not homebrew just because the table has
// D&D selected, or it would be shown as a removable custom chip.
const STANDARD_LANGUAGES = LANGUAGE_CATALOG.map(l => l.name);
const LANGUAGE_WORLDS = [
  { key: 'dnd', label: 'D&D (SRD)' },
  { key: 'bnb', label: 'Burrows & Badgers' },
];
function languageWorld(name) {
  const hit = LANGUAGE_CATALOG.find(l => l.name.toLowerCase() === String(name || '').trim().toLowerCase());
  return hit ? hit.world : null;   // null = homebrew, belongs to no world
}
// The languages a table may pick from. An unset or empty world list shows
// everything - a table that has never been configured must not get an empty
// picker.
function languagesForWorlds(worlds) {
  const on = new Set(Array.isArray(worlds) && worlds.length ? worlds : ['dnd', 'bnb']);
  return LANGUAGE_CATALOG.filter(l => on.has(l.world));
}
// v8.17: render text as an unknown script (unknown language, or a failed
// decipher check). Deterministic per (text,seed) so it doesn't reshuffle on
// every render; keeps whitespace + punctuation so it still looks like prose.
const SCRAMBLE_GLYPHS = 'ᚠᚢᚦᚨᚱᚲᚷᚹᚺᚾᛁᛄᛇᛈᛉᛊᛏᛒᛖᛗᛚᛜᛞᛟαβγδεζηθικλμνξοπρστυφχψωϐϑϒϓϔϕϖ';
function scrambleText(text, seed) {
  let h = (seed || 1) >>> 0, out = '';
  for (const ch of String(text || '')) {
    if (/\s/.test(ch)) { out += ch; continue; }
    if (/[.,!?;:'"()\[\]\---]/.test(ch)) { out += ch; continue; }
    h = (Math.imul(h, 1103515245) + 12345) >>> 0;
    out += SCRAMBLE_GLYPHS[h % SCRAMBLE_GLYPHS.length];
  }
  return out;
}
function speaksLanguage(entity, language) {
  const lang = String(language || '').trim().toLowerCase();
  if (!lang || lang === 'common') return true; // no language set / Common = readable
  const known = `${entity?.languages || ''} ${entity?.proficiencies || ''}`.toLowerCase();
  return known.includes(lang);
}

