  const sets = list.filter(o => o.op === 'set').map(o => Number(o.ft));
  if (sets.length) value = Math.max(...sets);
  const mins = list.filter(o => o.op === 'min').map(o => Number(o.ft));
  if (mins.length) value = Math.max(value, Math.max(...mins));
  for (const o of list) if (o.op === 'add') value += Number(o.ft);
  const caps = list.filter(o => o.op === 'cap').map(o => Number(o.ft));
  if (caps.length) value = Math.min(value, Math.min(...caps));
