    level: classLevelOf(entity), class: entity?.class || '', subclass: entity?.subclass || null,
    featureChoices: JSON.parse(JSON.stringify(entity?.featureChoices || {})),
    asiChoices: JSON.parse(JSON.stringify(entity?.asiChoices || {})),
    featureUses: JSON.parse(JSON.stringify(entity?.featureUses || {})),
    expertise: [...(entity?.expertise || [])],
