  if (!lr) return { entity, ok: false, reason: 'no legendary resistance', result: saveResult };
  if (lr.remaining <= 0) return { entity, ok: false, reason: 'no uses left', result: saveResult };
  if (saveResult && saveResult.success) return { entity, ok: false, reason: 'the save already succeeded', result: saveResult };
