function regionalEffectsOf(entity) { return entity?.regionalEffects || []; }
function reactionsOf(entity) { return entity?.reactions || []; }

// --- Spellcasting ---------------------------------------------------------------------
// A stat block prints the save DC and attack bonus outright; when it does they
// are authoritative and no derivation is attempted.
function monsterSpellSaveDc(entity) {
  const printed = Number(entity?.spellcasting?.saveDc ?? entity?.innateSpellcasting?.saveDc);
  if (Number.isFinite(printed) && printed > 0) return printed;
  const ability = entity?.spellcasting?.ability || entity?.innateSpellcasting?.ability;
  if (!ability) return null;
  return 8 + proficiencyBonusOf(entity) + abilityMod(effectiveStat(entity, ability));
}
function monsterSpellAttackBonus(entity) {
  const printed = Number(entity?.spellcasting?.attackBonus);
  if (Number.isFinite(printed)) return printed;
  const ability = entity?.spellcasting?.ability || entity?.innateSpellcasting?.ability;
  if (!ability) return null;
  return proficiencyBonusOf(entity) + abilityMod(effectiveStat(entity, ability));
}
// Innate spellcasting: at-will spells plus a per-day allowance. Uses are tracked
// in `innateUses`, keyed by spell name.
function innateSpellsOf(entity) {
  const inn = entity?.innateSpellcasting;
  if (!inn) return null;
  const used = entity?.innateUses || {};
  const perDay = [];
  for (const [times, names] of Object.entries(inn.perDay || {})) {
    for (const n of names) {
      const max = Math.max(0, Number(times) || 0);
      perDay.push({ name: n, max, used: Math.min(max, Number(used[n]) || 0), remaining: Math.max(0, max - (Number(used[n]) || 0)) });
    }
  }
  return { ability: inn.ability || null, saveDc: monsterSpellSaveDc(entity), atWill: inn.atWill || [], perDay };
}
function castInnateSpell(entity, name) {
  const inn = innateSpellsOf(entity);
  if (!inn) return { entity, ok: false, reason: 'no innate spellcasting' };
  if ((inn.atWill || []).includes(name)) return { entity, ok: true, reason: null, atWill: true };
  const slot = inn.perDay.find(p => p.name === name);
  if (!slot) return { entity, ok: false, reason: `${name} is not among its innate spells` };
  if (slot.remaining <= 0) return { entity, ok: false, reason: `${name} has no uses left today` };
  return { entity: { ...entity, innateUses: { ...(entity.innateUses || {}), [name]: slot.used + 1 } }, ok: true, reason: null, atWill: false };
}
function resetInnateSpells(entity) {
  return entity?.innateUses ? { ...entity, innateUses: {} } : entity;
}

// --- Traits as clauses -----------------------------------------------------------------
// Magic Resistance and any trait carrying `effects` reach the engine through the
// shared clause vocabulary, so nothing in the save or attack path knows what a
// monster trait is.
function monsterClauses(entity) {
  const out = [];
  if (entity?.magicResistance) {
    out.push({ name: 'Magic Resistance', rule: { saves: { advantageAgainstSpells: true } } });
  }
  for (const t of (entity?.traits || [])) {
    if (t?.effects) out.push({ name: t.name || 'trait', rule: t.effects });
  }
  return out;
}
// A stat-block summary for the sheet and the token panel.
function monsterProfile(entity) {
  return {
    size: sizeCategoryOf(entity), spaceFt: creatureSpaceFt(entity), reachFt: creatureReachFt(entity),
    saveBonuses: entity?.saveBonuses || {}, skillBonuses: entity?.skillBonuses || {},
    magicResistance: !!entity?.magicResistance,
    conditionImmunities: [...conditionImmunitiesOf(entity)],
    recharge: rechargeAbilitiesOf(entity),
    multiattack: multiattackOf(entity),
    legendaryActions: legendaryActionsOf(entity),
    legendaryResistances: legendaryResistancesOf(entity),
    lairActions: lairActionsOf(entity), regionalEffects: regionalEffectsOf(entity),
    reactions: reactionsOf(entity),
    innate: innateSpellsOf(entity),
    spellSaveDc: monsterSpellSaveDc(entity), spellAttackBonus: monsterSpellAttackBonus(entity),
    usesDeathSaves: usesDeathSavesFor(entity),
    traits: entity?.traits || [],
  };
}


// ============================================================================
// LIGHTING & SENSES (2014)  (v9.02)
// ============================================================================
// Four questions the engine previously conflated into one boolean:
//
//   1. LIGHT       what light level is at a point?          lightLevelAt
//   2. VISION      can this creature SEE that creature?     canSeeCreature
//   3. LINE OF SIGHT is the path unblocked by opaque cover?  hasLineOfSight
//   4. LINE OF EFFECT is the path unblocked by anything?     hasLineOfEffect
//
// and a fifth that is not vision at all:
//   5. LOCATION    does it KNOW where that creature is?     knowsLocationOf
//
// A creature can have line of sight and still not see (darkness, invisibility);
// it can be unable to see and still know the location (blindsight, tremorsense,
// or simply having heard it). Keeping these apart is the point of this section.

const LIGHT_LEVELS = ['bright', 'dim', 'darkness'];
// Obscurity follows from light: bright is clear, dim is lightly obscured,
// darkness is heavily obscured.
const OBSCURITY_BY_LIGHT = { bright: 'none', dim: 'lightly', darkness: 'heavily' };
// A heavily obscured area blocks vision entirely; a lightly obscured one gives
// disadvantage on Perception checks that rely on sight.
const OBSCURITY_EFFECT = {
  none: { blocksSight: false, perception: 'normal' },
  lightly: { blocksSight: false, perception: 'disadvantage' },
  heavily: { blocksSight: true, perception: 'disadvantage' },
};
function brighter(a, b) { return LIGHT_LEVELS.indexOf(a) <= LIGHT_LEVELS.indexOf(b) ? a : b; }

// --- Light -------------------------------------------------------------------
// A map's ambient light, and every light source on it. A source has a bright
// radius and a dim radius that extends beyond it (a torch: 20 bright, 40 dim).
function ambientLightOf(state, mapId) {
  const m = state?.maps?.[mapId || state?.currentMapId];
  const a = m?.ambientLight;
  return LIGHT_LEVELS.includes(a) ? a : 'bright';
}
function lightSourcesOn(state, mapId) {
  const id = mapId || state?.currentMapId;
  const out = [];
  for (const t of Object.values(state?.tokens || {})) {
    if (t.mapId !== id) continue;
    const e = state?.entities?.[t.entityId];
    const bright = Number(t.lightRadius ?? e?.lightRadius) || 0;
    if (bright <= 0) continue;
    const dim = Number(t.dimRadius ?? e?.dimRadius);
    out.push({ x: t.x, y: t.y, brightFt: bright, dimFt: Number.isFinite(dim) ? dim : bright * 2, id: t.id });
  }
  for (const l of (state?.lights?.[id] || [])) {
    const bright = Number(l.brightFt) || 0;
    out.push({ x: l.x, y: l.y, brightFt: bright, dimFt: Number(l.dimFt) || bright * 2, id: l.id });
  }
  return out;
}
// The light level at a point: the brightest any source makes it, floored by the
// map's ambient light.
function lightLevelAt(state, point, mapId) {
  let level = ambientLightOf(state, mapId);
  if (!point) return level;
  for (const s of lightSourcesOn(state, mapId)) {
    const ft = Math.hypot(s.x - point.x, s.y - point.y) / PX_PER_FOOT;
    if (ft <= s.brightFt) level = brighter(level, 'bright');
    else if (ft <= s.dimFt) level = brighter(level, 'dim');
  }
  return level;
}
function obscurityAt(state, point, mapId) { return OBSCURITY_BY_LIGHT[lightLevelAt(state, point, mapId)]; }

// --- Senses -------------------------------------------------------------------
// Every special sense a creature has, in feet. Darkvision comes through the
// magic-item layer so Goggles of Night are already included.
function sensesOf(entity) {
  // v12.8: all four resolved the same way. Three of them used to read the raw
  // entity field, so an item could grant darkvision and nothing else.
  const s = effectiveSenses(entity);
  return {
    darkvision: s.darkvision,
    blindsight: s.blindsight,
    tremorsense: s.tremorsense,
    truesight: s.truesight,
    blindBeyond: !!entity?.blindBeyondBlindsight,
  };
}
// What a creature with darkvision actually perceives at a given distance.
// "You can see in dim light within N feet as if it were bright light, and in
// darkness as if it were dim light. You can't discern colour in darkness."
function perceivedLight(entity, actualLevel, distFt) {
  const s = sensesOf(entity);
  const dist = Number(distFt) || 0;
  if (s.truesight > 0 && dist <= s.truesight) {
    return { level: 'bright', colorless: false, via: 'truesight' };
  }
  if (s.darkvision > 0 && dist <= s.darkvision) {
    if (actualLevel === 'darkness') return { level: 'dim', colorless: true, via: 'darkvision' };
    if (actualLevel === 'dim') return { level: 'bright', colorless: false, via: 'darkvision' };
  }
  return { level: actualLevel, colorless: false, via: 'normal' };
}
// The obscurity a viewer experiences looking at a point, after its senses.
function perceivedObscurity(entity, actualLevel, distFt) {
  return OBSCURITY_BY_LIGHT[perceivedLight(entity, actualLevel, distFt).level];
}

// --- THE vision question --------------------------------------------------------
// Can `viewer` SEE `target`? Answers with the reason, so a UI can explain it.
// Order matters: truesight beats everything, then blindness, then invisibility,
// then obscurity, then line of sight.
function canSeeCreature(state, viewerId, targetId) {
  const viewer = typeof viewerId === 'string' ? state?.entities?.[viewerId] : viewerId;
  const target = typeof targetId === 'string' ? state?.entities?.[targetId] : targetId;
  const no = (reason, extra = {}) => ({ canSee: false, reason, sense: null, ...extra });
  if (!viewer || !target) return no('unknown creature');

  const tokens = Object.values(state?.tokens || {});
  const vt = tokens.find(t => t.entityId === viewer.id);
  const tt = tokens.find(t => t.entityId === target.id);
  const distFt = (vt && tt && vt.mapId === tt.mapId) ? Math.hypot(vt.x - tt.x, vt.y - tt.y) / PX_PER_FOOT : null;
  if (vt && tt && vt.mapId !== tt.mapId) return no('on a different map');

  const s = sensesOf(viewer);
  const vis = conditionVisibilityProfile(viewer);
  const targetVis = conditionVisibilityProfile(target);

  // truesight sees through darkness, invisibility and illusion alike
  if (s.truesight > 0 && distFt != null && distFt <= s.truesight) {
    return { canSee: true, reason: 'truesight', sense: 'truesight', distFt };
  }
  // a blinded creature cannot see at all - but may still perceive by other means
  if (!vis.canSee) {
    if (s.blindsight > 0 && distFt != null && distFt <= s.blindsight) {
      return { canSee: true, reason: 'blindsight', sense: 'blindsight', distFt };
    }
    return no('the viewer is blinded', { distFt });
  }
  if (s.blindsight > 0 && distFt != null && distFt <= s.blindsight) {
    return { canSee: true, reason: 'blindsight', sense: 'blindsight', distFt };
  }
  // an invisible creature cannot be seen without a special sense
  if (targetVis.unseen) return no('the target is invisible', { distFt });

  // line of sight: opaque cover blocks vision
  if (vt && tt) {
    const walls = (state?.blockZones?.[vt.mapId] || []).map(z => ({ poly: blockToPolygon(z), opaque: z.opaque !== false }));
    const opaque = walls.filter(w => w.opaque).map(w => w.poly);
    if (!hasLineOfSight({ x: vt.x, y: vt.y }, { x: tt.x, y: tt.y }, opaque)) {
      return no('no line of sight', { distFt });
    }
  }
  // light, after the viewer's darkvision
  const level = tt ? lightLevelAt(state, { x: tt.x, y: tt.y }, tt.mapId) : 'bright';
  const perceived = perceivedLight(viewer, level, distFt ?? 0);
  const obscurity = OBSCURITY_BY_LIGHT[perceived.level];
  if (OBSCURITY_EFFECT[obscurity].blocksSight) {
    return no('the target is heavily obscured', { distFt, lightLevel: level, obscurity });
  }
  return {
    canSee: true, reason: perceived.via === 'darkvision' ? 'darkvision' : 'sight',
    sense: perceived.via, distFt, lightLevel: level, perceivedLevel: perceived.level,
    colorless: perceived.colorless, obscurity,
  };
}
// Does the viewer KNOW where the target is? Seeing is one way; blindsight and
// tremorsense are others; so is having noticed it without seeing it.
function knowsLocationOf(state, viewerId, targetId) {
  const seen = canSeeCreature(state, viewerId, targetId);
  if (seen.canSee) return { knows: true, via: seen.sense || 'sight', canSee: true };
  const viewer = typeof viewerId === 'string' ? state?.entities?.[viewerId] : viewerId;
  const target = typeof targetId === 'string' ? state?.entities?.[targetId] : targetId;
  const s = sensesOf(viewer);
  const dist = seen.distFt;
  if (s.tremorsense > 0 && dist != null && dist <= s.tremorsense) {
    // tremorsense needs the target on the ground, not flying or incorporeal
    const airborne = Number(target?.elevationFt) > 0 || target?.flying;
    if (!airborne) return { knows: true, via: 'tremorsense', canSee: false };
  }
  if (s.blindsight > 0 && dist != null && dist <= s.blindsight) {
    return { knows: true, via: 'blindsight', canSee: false };
  }
  // a creature that has been noticed is not hidden, even if unseen
  if (target && !target.hidden) return { knows: true, via: 'noticed', canSee: false };
  return { knows: false, via: null, canSee: false };
}
// Hiding: a creature can attempt to hide only when it is unseen or heavily
// obscured, and stays hidden until it is found or gives itself away.
function canAttemptHide(state, entityId) {
  const e = typeof entityId === 'string' ? state?.entities?.[entityId] : entityId;
  if (!e) return { ok: false, reason: 'unknown creature' };
  if (conditionVisibilityProfile(e).unseen) return { ok: true, reason: 'invisible' };
  const tokens = Object.values(state?.tokens || {});
  const t = tokens.find(x => x.entityId === e.id);
  if (!t) return { ok: false, reason: 'not on a map' };
  const obscurity = obscurityAt(state, { x: t.x, y: t.y }, t.mapId);
  if (obscurity === 'heavily') return { ok: true, reason: 'heavily obscured' };
  return { ok: false, reason: 'you must be unseen or heavily obscured to hide' };
}

// --- Passive Perception ------------------------------------------------------------
// 10 + Wisdom modifier + proficiency (or expertise, or half proficiency),
// +5 if the creature has advantage on the check, -5 if it has disadvantage.
// A stat block's printed value still wins.
function passivePerceptionOf(entity, opts = {}) {
  const printed = Number(entity?.passivePerception);
  const state = opts.state || null;
  const skill = opts.skill || 'Perception';
  let base = 10 + skillCheckMod(entity, skill) + featPassiveBonus(entity, skill) + itemPpBonus(entity);
  if (Number.isFinite(printed) && printed > 0 && !opts.ignorePrinted) base = printed;
  // advantage and disadvantage on the check are worth +/-5 to a passive score
  const modes = [];
  if (opts.advMode) modes.push(toShortAdv(opts.advMode));
  const cond = conditionRollContext(state || {}, { kind: 'check', actor: entity, actorId: entity?.id, skill });
  modes.push(toShortAdv(cond.advMode));
  // a lightly obscured target imposes disadvantage on sight-based Perception
  if (opts.obscurity === 'lightly' || opts.obscurity === 'heavily') modes.push('disadv');
  const combined = combineAdvModes(modes.filter(Boolean));
  const swing = combined === 'advantage' ? 5 : combined === 'disadvantage' ? -5 : 0;
  return {
    score: base + swing, base, swing, advMode: combined,
    reasons: cond.reasons, printed: Number.isFinite(printed) && printed > 0 ? printed : null,
  };
}
// A creature stays unnoticed while its Stealth beats the observer's passive score.
function noticesHiddenCreature(state, observerId, hiddenId, opts = {}) {
  const observer = typeof observerId === 'string' ? state?.entities?.[observerId] : observerId;
  const hidden = typeof hiddenId === 'string' ? state?.entities?.[hiddenId] : hiddenId;
  if (!observer || !hidden) return { notices: false, reason: 'unknown creature' };
  const seen = canSeeCreature(state, observerId, hiddenId);
  const pp = passivePerceptionOf(observer, { state, obscurity: seen.obscurity });
  const stealth = Number.isFinite(Number(opts.stealth)) ? Number(opts.stealth)
    : Number(hidden.hideCheck) || (10 + skillCheckMod(hidden, 'Stealth'));
  return {
    notices: pp.score >= stealth, passive: pp.score, stealth,
    reason: pp.score >= stealth ? 'passive Perception meets the Stealth check' : 'the hidden creature goes unnoticed',
  };
}


// ============================================================================
// ADVENTURING & ENVIRONMENT (2014)  (v9.03)
// ============================================================================
// Carrying capacity, falling, suffocation, underwater, extreme weather, forced
// march, food and water, and travel pace. Every hazard resolves through the
// UNIVERSAL d20 resolver (`resolveSaveWithConditions`) and every point of
// damage through the CENTRAL HP pipeline (`applyHpTransaction`) - nothing here
// rolls or subtracts on its own.
//
// Each subsystem is independently switchable, because most tables do not track
// rations. `CAMPAIGN_RULES_DEFAULT` is the shape; a campaign overrides it on
// `state.campaignRules`.
const CAMPAIGN_RULES_DEFAULT = {
  encumbrance: 'none',      // 'none' | 'variant'
  falling: true,
  suffocation: true,
  underwater: true,
  extremeWeather: false,
  forcedMarch: true,
  foodAndWater: false,
  travelPace: true,
};
function campaignRules(state) {
  return { ...CAMPAIGN_RULES_DEFAULT, ...(state?.campaignRules || {}) };
}
function ruleEnabled(state, key) {
  const v = campaignRules(state)[key];
  return v === true || (typeof v === 'string' && v !== 'none');
}

// --- Carrying capacity ------------------------------------------------------------
// Capacity is Strength x 15. Push, drag and lift is twice that. Both are
// multiplied by the size factor: doubled per size above Medium, halved for Tiny.
function sizeCarryFactor(entity) {
  const rank = sizeRank(entity);
  const medium = SIZE_INFO.Medium.rank;
  if (rank < medium) return sizeCategoryOf(entity) === 'Tiny' ? 0.5 : 1;
  return Math.pow(2, rank - medium);
}
function carryingCapacityOf(entity) {
  return Math.floor(effectiveStat(entity, 'str') * 15 * sizeCarryFactor(entity));
}
function pushDragLiftOf(entity) { return carryingCapacityOf(entity) * 2; }
function carriedWeightOf(entity) {
  return (entity?.items || []).reduce((s, i) => s + (Number(i?.weight) || 0) * (Number(i?.qty) || 1), 0);
}
// The variant encumbrance rule, applied only when the campaign asks for it.
// 5x STR: encumbered (-10 ft). 10x STR: heavily encumbered (-20 ft, and
// disadvantage on STR, DEX and CON checks, attacks and saves).
const ENCUMBRANCE_TIERS = [
  { id: 'heavy', label: 'Heavily encumbered', multiplier: 10, speedPenaltyFt: 20,
    effects: { checks: { disadvantageAbilities: ['str', 'dex', 'con'] },
      saves: { disadvantage: ['str', 'dex', 'con'] },
      attack: { selfByAbility: ['str', 'dex'], self: 'disadvantage' } } },
  { id: 'light', label: 'Encumbered', multiplier: 5, speedPenaltyFt: 10, effects: {} },
];
function encumbranceOf(entity, state = null) {
  const carried = carriedWeightOf(entity);
  const capacity = carryingCapacityOf(entity);
  const base = {
    carried, capacity, pushDragLift: pushDragLiftOf(entity),
    overCapacity: carried > capacity, tier: null, label: 'Unencumbered',
    speedPenaltyFt: 0, variant: false,
  };
  if (state && campaignRules(state).encumbrance !== 'variant') return base;
  if (!state) return base;                          // no campaign: no variant rule
  const str = effectiveStat(entity, 'str') * sizeCarryFactor(entity);
  for (const t of ENCUMBRANCE_TIERS) {
    if (carried > str * t.multiplier) {
      return { ...base, tier: t.id, label: t.label, speedPenaltyFt: t.speedPenaltyFt, variant: true, effects: t.effects };
    }
  }
  return { ...base, variant: true };
}
// Encumbrance reaches movement, checks, saves and attacks as ordinary clauses.
function encumbranceClauses(entity, state) {
  const e = encumbranceOf(entity, state);
  if (!e.variant || !e.tier) return [];
  return [{ name: e.label, rule: { movement: { speedPenaltyFt: e.speedPenaltyFt }, ...(e.effects || {}) } }];
}

// --- Falling ------------------------------------------------------------------------
// 1d6 bludgeoning per 10 feet, to a maximum of 20d6, and the creature lands prone.
const FALL_MAX_DICE = 20;
function fallingDamageDice(distanceFt) {
  return Math.max(0, Math.min(FALL_MAX_DICE, Math.floor((Number(distanceFt) || 0) / 10)));
}
function rollFallingDamage(distanceFt, opts = {}) {
  const dice = fallingDamageDice(distanceFt);
  if (!dice) return { dice: 0, total: 0, rolls: [] };
  if (opts.average) return { dice, total: dice * 3.5 | 0, rolls: [], average: true };
  const rng = typeof opts.rng === 'function' ? opts.rng : Math.random;
  const rolls = [];
  for (let i = 0; i < dice; i++) rolls.push(1 + Math.floor(rng() * 6));
  return { dice, total: rolls.reduce((a, b) => a + b, 0), rolls };
}

// --- Holding breath and suffocation ---------------------------------------------------
// Hold breath for 1 + CON modifier minutes (minimum 30 seconds). After that a
// creature survives CON modifier rounds (minimum 1) before dropping to 0 hit
// points and becoming unable to regain any until it can breathe again.
function holdBreathSeconds(entity) {
  const con = abilityMod(effectiveStat(entity, 'con'));
  return Math.max(30, (1 + con) * 60);
}
function suffocationRounds(entity) {
  return Math.max(1, abilityMod(effectiveStat(entity, 'con')));
}
// Advance a creature's air state by `seconds` without air. Returns the state and
// whether it has now run out.
function advanceSuffocation(entity, seconds, state = null) {
  if (state && !ruleEnabled(state, 'suffocation')) return { entity, status: 'disabled' };
  const held = Math.max(0, (Number(entity?.breath?.heldSeconds) || 0) + (Number(seconds) || 0));
  const limit = holdBreathSeconds(entity);
  if (held < limit) {
    return { entity: { ...entity, breath: { ...(entity.breath || {}), heldSeconds: held } },
      status: 'holding', heldSeconds: held, limitSeconds: limit, remainingSeconds: limit - held };
  }
  // out of air: count down the grace rounds (6 seconds each)
  const overflow = held - limit;
  const roundsGone = Math.floor(overflow / 6);
  const grace = suffocationRounds(entity);
  const next = { ...entity, breath: { heldSeconds: held, suffocatingRounds: roundsGone } };
  if (roundsGone < grace) {
    return { entity: next, status: 'suffocating', roundsGone, graceRounds: grace, remainingRounds: grace - roundsGone };
  }
  return { entity: next, status: 'out-of-air', roundsGone, graceRounds: grace, remainingRounds: 0 };
}
function resetBreath(entity) {
  if (!entity?.breath) return entity;
  const out = { ...entity }; delete out.breath; return out;
}

// --- Underwater ------------------------------------------------------------------------
// Without a swimming speed, every foot of swimming costs an extra foot.
function underwaterMovementFor(entity) {
  const swim = Number(entity?.speeds?.swim) || 0;
  return swim > 0
    ? { mode: 'swim', speedFt: swim, extraCostPerFoot: 0, note: 'has a swimming speed' }
    : { mode: 'walk', speedFt: Number(entity?.speeds?.walk) || 0, extraCostPerFoot: 1, note: 'swimming costs an extra foot per foot' };
}
// Melee weapons that work underwater; everything else has disadvantage.
const UNDERWATER_MELEE_OK = ['dagger', 'javelin', 'shortsword', 'spear', 'trident'];
// Ranged weapons that work underwater; everything else automatically misses
// beyond its normal range, and has disadvantage within it.
const UNDERWATER_RANGED_OK = ['crossbow', 'net', 'javelin', 'spear', 'dart', 'trident'];
function underwaterAttackRule(entity, weapon, opts = {}) {
  const name = String(weapon?.name || '').toLowerCase();
  const ranged = weaponIsRanged(weapon) || !!opts.thrown;
  const hasSwim = (Number(entity?.speeds?.swim) || 0) > 0;
  if (ranged) {
    const ok = UNDERWATER_RANGED_OK.some(w => name.includes(w));
    if (ok) return { mode: 'normal', autoMiss: false, reason: `${weapon?.name || 'this weapon'} works underwater` };
    const beyondNormal = Number(opts.distFt) > (Number(weapon?.range?.normal) || 0);
    if (beyondNormal) return { mode: 'normal', autoMiss: true, reason: 'a ranged attack underwater misses beyond its normal range' };
    return { mode: 'disadvantage', autoMiss: false, reason: 'ranged attacks underwater have disadvantage' };
  }
  if (hasSwim) return { mode: 'normal', autoMiss: false, reason: 'a swimming speed removes the penalty' };
  const ok = UNDERWATER_MELEE_OK.some(w => name.includes(w));
  return ok
    ? { mode: 'normal', autoMiss: false, reason: `${weapon?.name || 'this weapon'} works underwater` }
    : { mode: 'disadvantage', autoMiss: false, reason: 'melee attacks underwater have disadvantage without a swimming speed' };
}

// --- Weather, marching and starvation ----------------------------------------------------
// Each returns a HAZARD DESCRIPTOR; `resolveHazardSave` rolls it through the
// universal resolver so condition, armour and item modifiers all apply.
function extremeHeatHazard(entity, opts = {}) {
  // DC 5 CON save each hour, +1 per previous save this exposure. Creatures with
  // fire resistance or immunity, or no need to breathe or drink, are exempt.
  const mods = damageModsOf(entity);
  const exempt = mods.resistAll || (mods.immune?.has ? mods.immune.has('fire') : false) || !!entity?.heatAdapted;
  return { id: 'extremeHeat', ability: 'con', dc: 5 + (Number(opts.previousSaves) || 0),
    exempt, onFail: { exhaustion: 1 }, label: 'extreme heat' };
}
function extremeColdHazard(entity, opts = {}) {
  const mods = damageModsOf(entity);
  const exempt = mods.resistAll || (mods.immune?.has ? mods.immune.has('cold') : false) || !!entity?.coldAdapted;
  return { id: 'extremeCold', ability: 'con', dc: 10, exempt, onFail: { exhaustion: 1 }, label: 'extreme cold' };
}
// Forced march: beyond 8 hours of travel, a DC 10 + 1 per hour beyond CON save.
function forcedMarchHazard(entity, hoursTravelled) {
  const beyond = Math.max(0, Math.floor(Number(hoursTravelled) || 0) - 8);
  return { id: 'forcedMarch', ability: 'con', dc: 10 + beyond, exempt: beyond <= 0,
    onFail: { exhaustion: 1 }, label: `forced march (hour ${Math.floor(Number(hoursTravelled) || 0)})`, hoursBeyond: beyond };
}
// Food and water. A creature needs 1 lb of food and 1 gallon of water a day
// (2 in hot weather). Days without food beyond CON modifier cause exhaustion;
// a day without water causes it outright, or two levels if already exhausted.
function starvationCheck(entity, daysWithoutFood) {
  const grace = Math.max(0, abilityMod(effectiveStat(entity, 'con')));
  const days = Math.max(0, Math.floor(Number(daysWithoutFood) || 0));
  return { grace, days, exhaustionGained: days > grace ? 1 : 0, label: 'going without food' };
}
function dehydrationCheck(entity, opts = {}) {
  const half = !!opts.halfWater;
  const alreadyExhausted = exhaustionLevelOf(entity) > 0;
  if (half) return { dc: 15, ability: 'con', onFail: { exhaustion: 1 }, label: 'only half enough water' };
  return { automatic: true, exhaustionGained: alreadyExhausted ? 2 : 1, label: 'a day without water' };
}
// --- Travel pace -------------------------------------------------------------------------
const TRAVEL_PACES = {
  fast:   { id: 'fast',   perHourMiles: 4,   perDayMiles: 30, effect: '-5 to passive Perception', passivePenalty: 5, stealth: false },
  normal: { id: 'normal', perHourMiles: 3,   perDayMiles: 24, effect: 'none', passivePenalty: 0, stealth: false },
  slow:   { id: 'slow',   perHourMiles: 2,   perDayMiles: 18, effect: 'able to use stealth', passivePenalty: 0, stealth: true },
};
function travelPace(id) { return TRAVEL_PACES[id] || TRAVEL_PACES.normal; }
function travelDistance(paceId, hours) {
  const p = travelPace(paceId);
  return { miles: p.perHourMiles * Math.max(0, Number(hours) || 0), pace: p };
}

// --- THE hazard resolver ------------------------------------------------------------------
// Every environmental saving throw goes through the universal d20 resolver, so
// exhaustion, armour, magic items and conditions all apply automatically.
function resolveHazardSave(state, entityId, hazard, opts = {}) {
  const entity = state?.entities?.[entityId];
  if (!entity) return { ok: false, reason: 'unknown creature' };
  if (hazard.exempt) return { ok: true, skipped: true, reason: `${entity.name} is unaffected by ${hazard.label}`, success: true };
  const roll = resolveSaveWithConditions(state, entityId, {
    ability: hazard.ability, dc: hazard.dc, rng: opts.rng, d20a: opts.d20a, d20b: opts.d20b,
    reason: hazard.label, magical: false,
  });
  return { ok: true, skipped: false, success: roll.success, roll, hazard, reason: `${hazard.label}: DC ${hazard.dc} ${String(hazard.ability).toUpperCase()}` };
}
// Environmental damage always goes through the central HP pipeline, so
// resistances, temporary hit points and the unconscious/death rules apply.
function applyEnvironmentalDamage(entity, amount, opts = {}) {
  const raw = Math.max(0, Math.floor(Number(amount) || 0));
  const type = opts.type || 'Bludgeoning';
  // v9.03: `applyHpTransaction` takes an already-mitigated amount - the attack
  // path resolves resistance upstream. Environmental damage has no such caller,
  // so the wrapper resolves it here, through the same shared calculators.
  const mitigation = opts.mitigation || autoMitigationForType(type, damageModsOf(entity));
  const final = mitigation === 'immune' ? 0
    : mitigation === 'resist' ? Math.floor(raw / 2)
    : mitigation === 'weak' ? raw * 2
    : raw;
  const out = applyHpTransaction(entity, { delta: -final, type, source: opts.source || 'environment' });
  return { ...out, mitigation, rawAmount: raw, appliedAmount: final };
}


// ============================================================================
// PLAYER UI STATE MODEL (v9.08)
// ============================================================================
// Before this section, PlayerInterface carried 25 useState hooks. Several
// encoded the SAME concept in different shapes - `showSheet`, `showClaim`,
// `showDice`, `showDraw`, `showInit` and `creatingChar` are all "which modal is
// open", and only one can be true at a time, but nothing enforced that. Others
// (`castTargeting`, `aimingSpell`, `interactingId`, `measureMode`, `drawMode`)
// are all "what workflow is the pointer in", again mutually exclusive.
//
// THREE TIERS OF STATE. The distinction is the point of this model, and every
// field below is labelled with exactly one:
//
//   LOCAL      - this browser, this session. Selection, panels, focus, modals.
//                NEVER serialized into a campaign save and never sent to a peer.
//   PREFERENCE - this browser, persisted to localStorage. Density, reduced
//                motion, panel collapse. Survives reload; not campaign data.
//   CAMPAIGN   - authoritative shared state, owned by the DM's reducer.
//                Requests, turn order, resources. This model READS it through
//                selectors and never writes it directly.
//
// The rule that follows: a save file must round-trip without carrying a single
// field from the LOCAL tier. `assertNoEphemeralInSave` enforces it, and a test
// fails the build if it is violated.

// --- Enumerations ---------------------------------------------------------------
// Which section of the right-hand dock is showing.
// v9.22: the dock's tab ids. 'revealed' and 'sheet' are retained as legacy
// aliases so a stored preference from before the redesign still resolves.
const UI_PANELS = ['actions', 'character', 'spells', 'foes', 'chat', 'revealed', 'sheet', 'party', 'log'];
// A preference saved before v9.22 names a panel that no longer exists as a tab.
const DOCK_TAB_ALIASES = { revealed: 'foes', sheet: 'character' };
function normalizeDockTab(id) {
  const mapped = DOCK_TAB_ALIASES[id] || id;
  return DOCK_TAB_IDS.includes(mapped) ? mapped : DOCK_TAB_DEFAULT;
}
// Mobile navigation is a separate axis: a phone shows one section at a time and
// the dock is not present, so this cannot reuse UI_PANELS.
// v9.23: the mobile bottom-nav destinations. The old ids are kept so a stored
// preference from before the redesign still resolves via `normalizeMobileSection`.
const UI_MOBILE_SECTIONS = ['map', 'party', 'combat', 'character', 'chat', 'sheet', 'actions', 'foes'];
// The pointer can be in exactly one workflow. `null` is the neutral state.
const UI_TARGETING_MODES = ['spell', 'weapon', 'area', 'interact', 'measure', 'reminder'];
// v9.40: DERIVED from `MOVE_MODES`, the rules-side vocabulary. These were two
// hand-maintained lists that had drifted: the UI knew 'move' while the rules
// knew 'walk', and knew nothing of crawl, climb, swim or fly - so
// `UI_BEGIN_MOVEMENT` silently refused four of the eight real modes.
// 'move' is kept as an alias for the pre-v9.31 name.
//
// Written out rather than spread from `MOVE_MODE_IDS`, which is declared later
// in the file; a test asserts the two agree, so the duplication cannot drift
// silently the way it just did.
const UI_MOVEMENT_MODES = ['move', 'walk', 'dash', 'crawl', 'climb', 'swim', 'fly', 'teleport', 'forced'];
// One modal or drawer at a time.
// v9.40: `interact` joins the enum. It was a free-standing `interactingId`
// hook, which meant an object-interaction panel could be open at the same time
// as a modal - the exact overlap `ui.modal` exists to prevent.
const UI_MODALS = ['sheet', 'claim', 'create', 'dice', 'draw', 'initiative', 'settings', 'request', 'levelup', 'interact'];
// The sheet is either being played from or being edited.
const UI_SHEET_MODES = ['play', 'edit'];

// --- The authoritative request lifecycle ------------------------------------------
// A player proposes; the DM disposes. Before v9.08 the vocabulary was only
// pending / accepted / rejected, which conflated three genuinely different
// outcomes: a DM saying no, a request timing out, and a player withdrawing.
// A timed-out request was recorded as REJECTED, which is wrong - it tells the
// player the DM refused when in fact nobody answered.
const REQUEST_STATUS = {
  DRAFT: 'draft',          // being composed locally; the DM has not seen it
  SUBMITTED: 'submitted',  // sent, awaiting adjudication
  ACCEPTED: 'accepted',    // the DM approved it as proposed
  REJECTED: 'rejected',    // the DM refused it
  CORRECTED: 'corrected',  // the DM approved a MODIFIED version
  CANCELLED: 'cancelled',  // the player withdrew it before adjudication
  EXPIRED: 'expired',      // nobody answered within the TTL
};
const REQUEST_STATUSES = Object.values(REQUEST_STATUS);
// Which statuses are still live, and which are final.
const REQUEST_TERMINAL = new Set([
  REQUEST_STATUS.ACCEPTED, REQUEST_STATUS.REJECTED, REQUEST_STATUS.CORRECTED,
  REQUEST_STATUS.CANCELLED, REQUEST_STATUS.EXPIRED,
]);
// Legal transitions. Anything not listed is refused, so a resolved request can
// never be re-resolved and a draft can never jump straight to accepted.
const REQUEST_TRANSITIONS = {
  [REQUEST_STATUS.DRAFT]: [REQUEST_STATUS.SUBMITTED, REQUEST_STATUS.CANCELLED],
  [REQUEST_STATUS.SUBMITTED]: [
    REQUEST_STATUS.ACCEPTED, REQUEST_STATUS.REJECTED, REQUEST_STATUS.CORRECTED,
    REQUEST_STATUS.CANCELLED, REQUEST_STATUS.EXPIRED,
  ],
};
function requestStatusIsTerminal(status) { return REQUEST_TERMINAL.has(status); }
// Which live requests have timed out. Pure, so the sweep's DECISION is testable
// even though the sweep itself runs in a component effect. A timeout yields
// EXPIRED - never REJECTED, which would tell the player the DM refused.
function expiredRequests(pendingRequests, now = Date.now(), ttlMs = REQUEST_TTL_MS) {
  return Object.values(pendingRequests || {})
    .filter(r => r && !requestStatusIsTerminal(normalizeRequestStatus(r.status)))
    .filter(r => now - (Number(r.ts) || 0) >= ttlMs)
    .map(r => ({ id: r.id, peerId: r.peerId, kind: r.kind, status: REQUEST_STATUS.EXPIRED }));
}
function canTransitionRequest(from, to) {
  if (!REQUEST_STATUSES.includes(to)) return { ok: false, reason: `unknown status "${to}"` };
  if (from === to) return { ok: false, reason: `already ${to}` };
  const allowed = REQUEST_TRANSITIONS[from] || [];
  if (!allowed.includes(to)) {
    return { ok: false, reason: requestStatusIsTerminal(from) ? `${from} is final` : `cannot go from ${from} to ${to}` };
  }
  return { ok: true, reason: null };
}
// Legacy saves used 'pending'; and TTL expiry was recorded as 'rejected'.
function normalizeRequestStatus(status) {
  if (status === 'pending') return REQUEST_STATUS.SUBMITTED;
  return REQUEST_STATUSES.includes(status) ? status : REQUEST_STATUS.SUBMITTED;
}

// v9.92: what the PLAYER should be told about their own new-character request.
//
// Both call sites compared the request's status to `'pending'` - a string no
// request has carried since the lifecycle vocabulary landed (see
// `normalizeRequestStatus`, which exists precisely because `'pending'` is the
// LEGACY spelling of `'submitted'`). The "Waiting for the DM" state was
// therefore unreachable: a player pressed the button and the screen did not
// change, which reads exactly like a dead button.
//
// `sending` is the local half. The status can only change once the host has
// received the request and echoed state back, so without an optimistic state
// there is a round trip of silence no matter how correct the status check is.
const NEW_CHARACTER_GRANT = {
  NONE: 'none', SENDING: 'sending', WAITING: 'waiting',
  GRANTED: 'granted', DECLINED: 'declined', LAPSED: 'lapsed',
};
function newCharacterGrantView(request, opts = {}) {
  if (!request) {
    return opts.sending
      ? { state: NEW_CHARACTER_GRANT.SENDING, text: 'Sending your request\u2026', canAsk: false, busy: true }
      : { state: NEW_CHARACTER_GRANT.NONE, text: null, canAsk: true, busy: false };
  }
  switch (normalizeRequestStatus(request.status)) {
    case REQUEST_STATUS.ACCEPTED:
    case REQUEST_STATUS.CORRECTED:
      return { state: NEW_CHARACTER_GRANT.GRANTED, text: 'The DM approved your new character.', canAsk: false, busy: false };
    case REQUEST_STATUS.REJECTED:
      return { state: NEW_CHARACTER_GRANT.DECLINED, text: 'The DM declined your request.', canAsk: true, busy: false };
    case REQUEST_STATUS.EXPIRED:
      return { state: NEW_CHARACTER_GRANT.LAPSED, text: 'Nobody answered in time. You can ask again.', canAsk: true, busy: false };
    case REQUEST_STATUS.CANCELLED:
      return { state: NEW_CHARACTER_GRANT.NONE, text: null, canAsk: true, busy: false };
    default:
      // submitted, or a draft that has been handed to the sender
      return { state: NEW_CHARACTER_GRANT.WAITING,
        text: 'Sent to the DM - waiting for approval\u2026', canAsk: false, busy: true };
  }
}

// --- The LOCAL slice ---------------------------------------------------------------
// Everything here is ephemeral. Recreated on load, discarded on unload.
// v9.40: the shape of an active workflow. Every field a flow needs to resume
// after a re-render lives here; nothing about a flow is kept in a component.
//
// `pointer` is the one concession to frequency: a pointer position changes many
// times a second and putting every one through the reducer would be wasteful.
// It is stored HERE rather than in a component so it cannot outlive its
// workflow - the bug that made `areaPoint` leak between casts.
const UI_WORKFLOW_FLOWS = ['attack', 'cast', 'area', 'movement', 'contest', 'standard', 'spellPicker', 'placement'];
function makeUiWorkflow({ flow, stage = null, actorId = null, targets = [],
  spellId = null, weaponId = null, slotId = null, castLevel = null,
  placement = null, destination = null, mode = null, props = {} } = {}) {
  return {
    flow, stage, actorId,
    targets: [...targets],        // TOKEN ids, in selection order
    spellId, weaponId, slotId, castLevel,
    placement,                    // area: { origin, angle, shape, sizeFt }
    destination,                  // movement: { x, y }
    mode,                         // movement mode, or shove mode
    pointer: null,                // high-frequency, scoped to this workflow
    result: null,                 // v9.41: the host's answer, when it refused
    // v9.46: the unified targeting context (v9.29). Held HERE so the map, the
    // panel list and the keyboard all modify one selection - previously each
    // flow kept its own and the map knew about none of them.
    targeting: null,
    props,                        // whatever the router handed over
  };
}
// v9.41: where a refused workflow should send the player back to. A rejection
// is usually about the thing chosen LAST, so returning to the final decision
// point is both the shortest fix and the least surprising.
function uiStageForRetry(workflow, result) {
  if (!workflow) return null;
  const why = String(result?.explanation || '').toLowerCase();
  if (/slot|level/.test(why) && workflow.flow === 'cast') return 'pickSlot';
  if (/range|reach|see|target/.test(why)) return workflow.flow === 'attack' ? 'pickTarget' : 'target';
  if (/weapon|ammunition|ammo/.test(why)) return 'pickWeapon';
  // otherwise leave the player where they were: re-deciding everything to fix
  // one problem is worse than staying put
  return workflow.stage;
}
function initialPlayerUiState(overrides = {}) {
  return {
    // selection -- LOCAL
    selectedOwnedTokenId: null,   // the token this player is acting with
    selectedTargetTokenId: null,  // what they are acting upon
    hoveredTokenId: null,

    // panels and navigation -- LOCAL
    rightPanel: 'revealed',       // one of UI_PANELS
    mobileSection: 'map',         // one of UI_MOBILE_SECTIONS
    leftCollapsed: false,
    rightCollapsed: false,

    // workflows -- LOCAL, and mutually exclusive by construction
    targeting: null,              // { mode, sourceId, spellId?, weaponId?, radiusFt? }
    movement: null,               // { mode, tokenId, fromX, fromY, usedFt }

    // v9.40: THE active gameplay workflow. Previously this lived in eleven
    // separate `useState` hooks inside `PlayerInterface` - `activeWorkflow`,
    // `castTargeting`, `aimingSpell`, `areaPoint`, `areaAim`, `movePoint`,
    // `interactingId` and more - which meant nothing prevented two from being
    // set at once. One object, one reducer, one exclusivity rule.
    keyboardTokenId: null,        // v9.43: which token holds keyboard focus
    // v9.44: the radial is a SECONDARY shortcut, so it needs its own slot.
    // Deriving it from the actor selection (as v9.40 briefly did) meant every
    // single click popped the menu - the opposite of secondary.
    radialTokenId: null,
    workflow: null,               // see `makeUiWorkflow` for the shape
    pendingIntentId: null,        // set while a submitted workflow awaits the host
    lastOutcome: null,            // v9.41: the host's last authoritative answer

    // modals -- LOCAL, at most one
    modal: null,                  // { id, props } where id is in UI_MODALS
    lastFocusedElementId: null,   // restored when a modal closes

    // sheet -- LOCAL
    sheetMode: 'play',            // play | edit
    sheetTab: 'core',

    // requests -- LOCAL VIEW of campaign data
    draftRequest: null,           // composed but not yet submitted
    unreadChatCount: 0,
    lastReadChatTs: 0,
    lastReadChatTs: 0,

    ...overrides,
  };
}
// PREFERENCE tier: persisted, and deliberately a separate object so it can be
// saved and restored without dragging ephemeral state along.
function initialPlayerUiPrefs(overrides = {}) {
  return {
    density: 'comfortable',       // comfortable | compact
    reducedMotion: null,          // null = follow the OS; true/false = explicit
    leftCollapsed: false,
    rightCollapsed: false,
    rightPanel: 'revealed',       // the panel to reopen on next load
    endTurnBinding: null,         // v9.21: null = the default (Alt+E)
    radialMenu: true,             // v9.25: the radial is optional
    ...overrides,
  };
}
const PLAYER_UI_PREFS_KEY = 'plagues-call.ui.prefs.v1';
function loadPlayerUiPrefs() {
  try {
    const raw = localStorage.getItem(PLAYER_UI_PREFS_KEY);
    return initialPlayerUiPrefs(raw ? JSON.parse(raw) : {});
  } catch { return initialPlayerUiPrefs(); }
}
function savePlayerUiPrefs(prefs) {
  try { localStorage.setItem(PLAYER_UI_PREFS_KEY, JSON.stringify(initialPlayerUiPrefs(prefs))); } catch {}
  return prefs;
}
// Does the user want reduced motion? An explicit preference wins; otherwise
// follow the OS.
function prefersReducedMotion(prefs) {
  if (prefs?.reducedMotion === true || prefs?.reducedMotion === false) return prefs.reducedMotion;
  try { return !!window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches; } catch { return false; }
}

// --- The LOCAL reducer -------------------------------------------------------------
// Pure. Every transition that must be mutually exclusive is enforced HERE rather
// than by the discipline of whoever calls setState.
function playerUiReducer(ui, action) {
  const s = ui || initialPlayerUiState();
  switch (action.type) {
    // --- selection ---------------------------------------------------------
    case 'UI_SELECT_OWNED':
      // changing who you are acting with abandons any workflow in progress -
      // a spell aimed by one character cannot be finished by another
      return { ...s, selectedOwnedTokenId: action.tokenId || null, targeting: null, movement: null };
    case 'UI_SELECT_TARGET':
      return { ...s, selectedTargetTokenId: action.tokenId || null };
    case 'UI_CLEAR_SELECTION':
      return { ...s, selectedOwnedTokenId: null, selectedTargetTokenId: null, targeting: null, movement: null };
    case 'UI_HOVER':
      return { ...s, hoveredTokenId: action.tokenId || null };

    // --- panels and navigation ---------------------------------------------
    case 'UI_SET_PANEL':
      if (!UI_PANELS.includes(action.panel)) return s;
      return { ...s, rightPanel: action.panel, rightCollapsed: false };
    case 'UI_SET_MOBILE_SECTION':
      if (!UI_MOBILE_SECTIONS.includes(action.section)) return s;
      return { ...s, mobileSection: action.section };
    case 'UI_TOGGLE_PANEL_COLLAPSE':
      return action.side === 'left' ? { ...s, leftCollapsed: !s.leftCollapsed } : { ...s, rightCollapsed: !s.rightCollapsed };

    // --- workflows: mutually exclusive by construction ----------------------
    // ===== v9.40: THE workflow lifecycle ==================================
    // Opening a workflow clears every other one, plus targeting, movement and
    // any half-finished target selection. Exclusivity is enforced HERE rather
    // than by each caller remembering to tidy up - which is what let
    // `activeWorkflow` and `castTargeting` both be set at once.
    // v9.43: keyboard focus on the map. Kept separate from SELECTION: moving
    // focus with the arrows must not select, or a player could not look around
    // without changing what they are acting with.
    case 'UI_FOCUS_TOKEN':
      return { ...s, keyboardTokenId: action.tokenId || null };
    case 'UI_OPEN_RADIAL':
      return { ...s, radialTokenId: action.tokenId || null };
    case 'UI_CLOSE_RADIAL':
      return { ...s, radialTokenId: null };
    case 'UI_OPEN_WORKFLOW': {
      if (!UI_WORKFLOW_FLOWS.includes(action.flow)) return s;
      return {
        ...s,
        workflow: makeUiWorkflow({
          flow: action.flow,
          actorId: action.actorId || s.selectedOwnedTokenId || null,
          ...(action.props || {}),
          props: action.props || {},
        }),
        pendingIntentId: null,
        targeting: null, movement: null,
        // the map-level target selection SURVIVES: a workflow keeps its own
        // `targets` list, and `selectedTargetTokenId` is a separate layer the
        // player unwinds separately with Escape
      };
    }
    case 'UI_WORKFLOW_PATCH': {
      if (!s.workflow) return s;
      // a patch may not change which flow is running; that needs OPEN
      const { flow, ...rest } = action.patch || {};
      return { ...s, workflow: { ...s.workflow, ...rest } };
    }
    case 'UI_WORKFLOW_POINTER': {
      // high-frequency: scoped to the workflow so it cannot outlive it
      if (!s.workflow) return s;
      // v9.51: a MOVEMENT workflow also records the destination, so the
      // confirm payload has one without re-deriving it from the pointer.
      const patch = { pointer: action.point || null };
      if (s.workflow.flow === 'movement' && action.point) {
        patch.destination = action.accepted || action.point;
      }
      return { ...s, workflow: { ...s.workflow, ...patch } };
    }
    // v9.46: the context and the target list move together, so a selection
    // made on the map and one made in the panel are the same selection.
    case 'UI_WORKFLOW_TARGETING':
      if (!s.workflow) return s;
      return { ...s, workflow: { ...s.workflow, targeting: action.ctx || null,
        targets: action.ctx ? [...(action.ctx.selected || [])] : s.workflow.targets } };
    case 'UI_WORKFLOW_ADD_TARGET': {
      if (!s.workflow || !action.tokenId) return s;
      const targets = [...s.workflow.targets, action.tokenId];
      return { ...s, workflow: { ...s.workflow, targets,
        targeting: s.workflow.targeting
          ? { ...s.workflow.targeting, selected: targets } : null } };
    }
    case 'UI_WORKFLOW_REMOVE_TARGET': {
      if (!s.workflow) return s;
      const at = s.workflow.targets.lastIndexOf(action.tokenId);
      if (at < 0) return s;
      const targets = s.workflow.targets.filter((_, i) => i !== at);
      return { ...s, workflow: { ...s.workflow, targets,
        targeting: s.workflow.targeting
          ? { ...s.workflow.targeting, selected: targets } : null } };
    }
    case 'UI_WORKFLOW_PENDING':
      if (!s.workflow) return s;
      return { ...s, pendingIntentId: action.intentId || null };
    // v9.41: what the host's answer does to the workflow.
    //
    //   accepted   the outcome is authoritative; the workflow closes
    //   corrected  the workflow stays open showing requested vs actual
    //   rejected   the workflow stays open with the player's CHOICES INTACT,
    //              returned to the stage that can fix the problem
    //   expired    same as rejected, but says the request timed out
    //
    // The rule that matters: a result for a DIFFERENT intent is ignored, so a
    // late answer to an abandoned workflow cannot close the current one.
    case 'UI_WORKFLOW_RESULT': {
      const r = action.result;
      if (!r || !s.workflow) return s;
      if (s.pendingIntentId && r.intentId && r.intentId !== s.pendingIntentId) return s;
      const status = r.status;
      if (status === INTENT_STATE.ACCEPTED) {
        // v9.47: an accepted ATTACK with attacks remaining keeps the flow open,
        // the weapon retained and the target cleared - so a second attack is
        // one click rather than five. `attacksLeft` comes from the host's
        // outcome, not a client guess.
        const left = Number(r.outcome?.attacksLeft);
        if (s.workflow?.flow === 'attack' && Number.isFinite(left) && left > 0) {
          return {
            ...s, pendingIntentId: null,
            workflow: { ...s.workflow,
              stage: 'pickTarget',            // keep the weapon, choose again
              targets: [],
              targeting: s.workflow.targeting ? { ...s.workflow.targeting, selected: [] } : null,
              result: { status, explanation: r.explanation || null,
                correction: null, requested: null, actual: null,
                attacksLeft: left },
            },
            lastOutcome: { status, explanation: r.explanation || null, outcome: r.outcome || null },
          };
        }
        return { ...s, workflow: null, pendingIntentId: null, targeting: null, movement: null,
          lastOutcome: { status, explanation: r.explanation || null, outcome: r.outcome || null } };
      }
      // everything else keeps the workflow open so the player can see what
      // happened and retry.
      //
      // v11.1: but a CORRECTED action ALREADY HAPPENED - the host agreed to
      // something different, it did not refuse. Keeping the target selection
      // alive meant the next action inherited it: pick one target for a
      // one-target spell, have the cast corrected, and the following spell
      // opened with its single slot already filled and answered "no room left"
      // on the first click. The result stays visible; the selection does not.
      const completed = r.status === INTENT_STATE.CORRECTED;
      return {
        ...s,
        pendingIntentId: null,
        workflow: {
          ...s.workflow,
          stage: uiStageForRetry(s.workflow, r),
          ...(completed ? {
            targets: [],
            targeting: s.workflow.targeting ? { ...s.workflow.targeting, selected: [] } : null,
          } : {}),
          result: {
            status,
            explanation: r.explanation || null,
            correction: r.correction || null,
            // a correction shows BOTH numbers; a rejection shows the reason
            requested: r.correction ? r.correction.requested ?? null : null,
            actual: r.correction ? r.correction.actual ?? null : null,
          },
        },
        lastOutcome: { status, explanation: r.explanation || null, outcome: r.outcome || null },
      };
    }
    case 'UI_WORKFLOW_CLEAR_RESULT':
      if (!s.workflow) return s;
      return { ...s, workflow: { ...s.workflow, result: null } };

    case 'UI_CLOSE_WORKFLOW':
      return { ...s, workflow: null, pendingIntentId: null, targeting: null, movement: null };

    case 'UI_BEGIN_TARGETING':
      if (!UI_TARGETING_MODES.includes(action.mode)) return s;
      // starting to aim cancels any movement in progress, and vice versa
      return { ...s, targeting: { mode: action.mode, sourceId: action.sourceId || s.selectedOwnedTokenId || null, ...action.payload }, movement: null };
    case 'UI_CANCEL_TARGETING':
      return { ...s, targeting: null };
    case 'UI_BEGIN_MOVEMENT':
      if (!UI_MOVEMENT_MODES.includes(action.mode)) return s;
      return { ...s, movement: { mode: action.mode, tokenId: action.tokenId || s.selectedOwnedTokenId || null, usedFt: 0, ...action.payload }, targeting: null };
    case 'UI_UPDATE_MOVEMENT':
      if (!s.movement) return s;
      return { ...s, movement: { ...s.movement, ...action.patch } };
    case 'UI_CANCEL_MOVEMENT':
      return { ...s, movement: null };

    // --- modals: at most one, and focus is restored on close ----------------
    case 'UI_OPEN_MODAL':
      if (!UI_MODALS.includes(action.id)) return s;
      return { ...s, modal: { id: action.id, props: action.props || {} },
        lastFocusedElementId: action.returnFocusTo || s.lastFocusedElementId };
    case 'UI_CLOSE_MODAL':
      return { ...s, modal: null };
    case 'UI_SET_FOCUS':
      return { ...s, lastFocusedElementId: action.elementId || null };

    // --- sheet --------------------------------------------------------------
    case 'UI_SET_SHEET_MODE':
      if (!UI_SHEET_MODES.includes(action.mode)) return s;
      return { ...s, sheetMode: action.mode };
    case 'UI_SET_SHEET_TAB':
      return { ...s, sheetTab: action.tab || 'core' };

    // --- draft requests -----------------------------------------------------
    case 'UI_DRAFT_REQUEST':
      return { ...s, draftRequest: { ...(action.request || {}), status: REQUEST_STATUS.DRAFT } };
    case 'UI_DISCARD_DRAFT':
      return { ...s, draftRequest: null };
    case 'UI_SUBMIT_DRAFT':
      // the draft leaves local state; the campaign reducer now owns it
      return { ...s, draftRequest: null };

    // --- chat ---------------------------------------------------------------
    case 'UI_CHAT_READ':
      return { ...s, unreadChatCount: 0, lastReadChatTs: action.ts || Date.now() };
    case 'UI_CHAT_RECOUNT':
      return { ...s, unreadChatCount: Math.max(0, Number(action.count) || 0) };

    case 'UI_RESET':
      return initialPlayerUiState();
    default:
      return s;
  }
}

// --- Selectors -------------------------------------------------------------------
// The read API. Components ask these questions rather than reaching into either
// state tree, so a change to either shape touches one place.

// The player's primary controlled character. A claim may include familiars and
// DM-lent PCs; the PRIMARY one is the claimed PC, falling back to the current
// selection so a player controlling only a familiar still has a subject.
function selectPrimaryCharacter(state, peerId, ui = null) {
  const claim = state?.claims?.[peerId];
  if (claim?.pc && state.entities?.[claim.pc]) return state.entities[claim.pc];
  if (ui?.selectedOwnedTokenId) {
    const tok = state?.tokens?.[ui.selectedOwnedTokenId];
    const ent = tok && state.entities?.[tok.entityId];
    if (ent) return ent;
  }
  const first = (claim?.familiars || [])[0] || (claim?.controlledPcs || [])[0];
  return (first && state?.entities?.[first]) || null;
}
function selectOwnedEntityIds(state, peerId) {
  const claim = state?.claims?.[peerId];
  if (!claim) return [];
  return [claim.pc, ...(claim.familiars || []), ...(claim.controlledPcs || [])].filter(Boolean);
}
// Is it this player's turn? Reports why, so the UI can say "waiting for Brann"
// rather than just disabling everything.
function selectTurnStatus(state, peerId) {
  const init = state?.initiative;
  const owned = new Set(selectOwnedEntityIds(state, peerId));
  if (!init || !Array.isArray(init.entries) || !init.entries.length) {
    return { inCombat: false, isMyTurn: false, activeEntityId: null, activeName: null, reason: 'not in combat' };
  }
  const active = init.entries[init.turn]?.entityId || null;
  const activeEnt = active ? state.entities?.[active] : null;
  const isMine = !!active && owned.has(active);
  return {
    inCombat: true, isMyTurn: isMine, activeEntityId: active,
    activeName: activeEnt?.name || null, round: init.round || 1,
    reason: isMine ? 'your turn' : `waiting for ${activeEnt?.name || 'another creature'}`,
  };
}
// What the character can still spend this turn. Combines the action economy
// with the conditions that suppress it, so a stunned character reports zero.
function selectActionResources(state, entityId) {
  const e = state?.entities?.[entityId];
  if (!e) return null;
  const econ = economyOf(state, e);   // v11.0: the readout must agree with the rules
  const profile = conditionEconomyProfile(e);
  const surprised = isSurprised(e);
  const prog = resolveMulticlassProgression(e);
  return {
    action: !econ.action && profile.canTakeActions && !surprised,
    bonus: !econ.bonus && profile.canTakeBonusActions && !surprised,
    reaction: !econ.reaction && profile.canTakeReactions && !surprised,
    attacksMade: Number(econ.attacksMade) || 0,
    attacksPerAction: attacksPerAction(e),
    features: (prog.resources || []).map(r => ({
      id: r.id, name: r.name, max: r.max, left: featureUsesLeft(e, r.id), recharge: r.recharge,
    })),
    blockedBy: !profile.canTakeActions ? 'incapacitated' : surprised ? 'surprised' : null,
  };
}
// Movement remaining, with the reason when it is zero.
function selectMovementRemaining(state, entityId) {
  const e = state?.entities?.[entityId];
  if (!e) return null;
  const mv = state?.movement?.entityId === entityId ? state.movement : null;
  const budget = moveBudget(e, mv || { mode: 'walk', usedFt: 0, dashCount: 0 });
  const csp = conditionSpeedProfile(e);
  return {
    remainingFt: budget.remainingFt, speedFt: budget.speed, usedFt: budget.usedFt,
    costMultiplier: budget.costMult, mode: budget.mode, dashCount: budget.dashCount,
    blockedBy: !csp.canMove ? 'cannot move' : csp.speedOverride === 0 ? 'speed is 0' : isSurprised(e) ? 'surprised' : null,
  };
}
// What the character is concentrating on, if anything.
function selectConcentration(state, entityId) {
  const e = state?.entities?.[entityId];
  if (!e?.concentratingOn) return { active: false, spellName: null, effectId: null };
  return {
    active: true,
    spellName: typeof e.concentratingOn === 'string' ? e.concentratingOn : e.concentratingOn.name || 'a spell',
    effectId: typeof e.concentratingOn === 'object' ? e.concentratingOn.effectId || null : null,
  };
}
// Requests this player owns, split into live and resolved, newest first.
// A local draft is folded in so the UI has one list to render.
function selectPendingRequests(state, peerId, ui = null) {
  const all = Object.values(state?.pendingRequests || {})
    .filter(r => r && r.peerId === peerId)
    .map(r => ({ ...r, status: normalizeRequestStatus(r.status) }))
    .sort((a, b) => (b.ts || 0) - (a.ts || 0));
  const live = all.filter(r => !requestStatusIsTerminal(r.status));
  const resolved = all.filter(r => requestStatusIsTerminal(r.status));
  const draft = ui?.draftRequest ? [{ ...ui.draftRequest, status: REQUEST_STATUS.DRAFT, local: true }] : [];
  return { draft: draft[0] || null, live, resolved, all: [...draft, ...all], liveCount: live.length };
}
// One call for everything the player HUD needs, so a component does not make
// eight separate selector calls and drift out of sync between them.
function selectPlayerHud(state, peerId, ui = null) {
  const character = selectPrimaryCharacter(state, peerId, ui);
  const id = character?.id || null;
  return {
    character,
    turn: selectTurnStatus(state, peerId),
    resources: id ? selectActionResources(state, id) : null,
    movement: id ? selectMovementRemaining(state, id) : null,
    concentration: id ? selectConcentration(state, id) : { active: false, spellName: null, effectId: null },
    requests: selectPendingRequests(state, peerId, ui),
  };
}

// --- The tier boundary -------------------------------------------------------------
// Fields that must NEVER appear in a campaign save. Checked by a test, so the
// boundary is enforced rather than merely documented.
const EPHEMERAL_UI_KEYS = Object.keys(initialPlayerUiState());
function assertNoEphemeralInSave(saveObject) {
  const found = [];
  const walk = (node, path, depth) => {
    if (!node || typeof node !== 'object' || depth > 3) return;
    for (const k of Object.keys(node)) {
      // `movement` is a legitimate CAMPAIGN field (the shared movement
      // transaction) as well as a local workflow name, so it is exempt at the
      // top level of state and only flagged inside a serialized ui blob.
      if (EPHEMERAL_UI_KEYS.includes(k) && k !== 'movement') found.push(`${path}${k}`);
      if (k === 'ui' || k === 'playerUi') found.push(`${path}${k}`);
    }
    for (const [k, v] of Object.entries(node)) walk(v, `${path}${k}.`, depth + 1);
  };
  walk(saveObject, '', 0);
  return { clean: found.length === 0, offenders: [...new Set(found)] };
}


// ============================================================================
// PLAYER FIELD PERMISSIONS (v9.09)
// ============================================================================
// One flat `PLAYER_FIELD_WHITELIST` decided every player write, and it had
// drifted badly:
//
//   * `resist`, `immune`, `vulnerable` were player-writable. A client could
//     grant itself immunity to fire by editing its own sheet.
//   * `ac`, `passivePerception`, `proficiencyBonus` were writable even though
//     they are DERIVED - a player could set AC 30, and the value would be
//     silently overwritten the next time the gear manager recomputed it. The
//     control could not round-trip.
//   * `spellSlotsMax`, `armorProfs`, `background` (build-time choices) sat in
//     the same bucket as `spellSlotsUsed` (live play), so a campaign that
//     wanted locked builds could not have one.
//   * Live resources went through the same generic `field_set` as cosmetic
//     text, so nothing validated that spending a slot you did not have was
//     refused.
//
// Three categories now, each with its own rules:
//
//   LIVE      spent/current values that change constantly during play.
//             Player-writable, but ONLY through dedicated validated
//             transactions - never through a generic patch.
//   BUILD     character construction. Player-writable only in EDIT mode, and
//             only if campaign permissions allow it.
//   DM        secrets and rules overrides. DM-only unless explicitly delegated.
//
// A fourth implicit category, DERIVED, is writable by nobody: those fields are
// computed, and a control that writes them cannot round-trip.

const FIELD_CATEGORY = { LIVE: 'live', BUILD: 'build', DM: 'dm', DERIVED: 'derived', COSMETIC: 'cosmetic' };

// --- LIVE: spent-during-play state, each with a dedicated transaction --------
// The value is the action a player must use. A generic patch touching any of
// these is refused with that action named, so the error message is actionable.
const LIVE_FIELDS = {
  hp: 'player_hp',                    // current hit points
  tempHp: 'player_temp_hp',
  spellSlotsUsed: 'player_spend_slot',
  pactSlotsUsed: 'player_spend_pact_slot',
  featureUses: 'player_feature_use',
  economy: 'player_economy',
  movementUsed: 'player_move',
  deathSaves: 'player_death_save',
  concentratingOn: 'player_concentration',
  hitDiceUsed: 'player_spend_hit_die',
  conditions: 'player_condition',
  exhaustion: 'player_exhaustion',
};
// --- BUILD: character construction, edit mode only ---------------------------
const BUILD_FIELDS = new Set([
  'classes', 'class', 'subclass', 'level',
  'stats', 'saveProfs', 'skillProfs', 'expertise', 'toolExpertise',
  'weaponProfs', 'armorProfs', 'toolProfs',
  'background', 'customBackground', 'backgroundSkillChoices', 'backgroundToolChoices',
  'backgroundLanguageChoices', 'proficiencyReplacements',
  'feats', 'asiChoices', 'featureChoices',
  'spellbook', 'preparedSpells', 'spellcastingAbility', 'casterProgression',
  'spellSlotsMax', 'pactSlots', 'hitDicePools', 'hitDice',
  'race', 'raceProfs', 'languages', 'speeds', 'unarmoredDefense', 'halfProficiency',
  'weapons', 'armor', 'shield', 'handsTotal', 'items', 'inventory', 'money',
]);
// --- DM: secrets and rules overrides ----------------------------------------
const DM_FIELDS = new Set([
  'resist', 'immune', 'vulnerable',           // arbitrary damage mods
  'conditionImmunities', 'immunities',
  'dmNotes', 'secretNotes', 'hidden', 'hiddenConditions',
  'acOverride', 'attacksPerAction', 'proficiencyBonus', 'preparedLimit',
  'saveBonuses', 'skillBonuses', 'magicResistance',
  'legendaryActions', 'legendaryResistances', 'lairActions', 'regionalEffects',
  'rechargeAbilities', 'multiattack', 'innateSpellcasting', 'spellcasting',
  'traits', 'blindsight', 'tremorsense', 'truesight',
  'usesDeathSaves', 'namedNpc', 'cr', 'xpValue',
  'attunementLimit', 'ignoreArmorStrengthReq',
  // v11.3: SIZE. `sizeCategory` and `size` were in no set at all, so
  // `fieldCategory` returned null and `canPlayerWriteField` refused them as
  // "not a recognised field" - a check that runs BEFORE the `ctx.isDM`
  // branch, so the GM could not change a creature's size either. Both size
  // controls wrote to a field the write path threw away.
  //
  // DM rather than BUILD: size is a stat-block fact about a creature, not
  // something a player chooses during character building. `reach` and `scale`
  // belong with it for the same reason.
  'sizeCategory', 'size', 'reach', 'scale',
]);
// --- DERIVED: computed, writable by nobody -----------------------------------
// A control that writes one of these cannot round-trip: the value is
// recomputed from its inputs and the write is silently lost. Such controls must
// be rendered read-only.
const DERIVED_FIELDS = new Set([
  'ac',                 // resolveArmorClass
  'passivePerception',  // passivePerceptionOf  (a MONSTER's printed value is a DM field)
  'initBonus',          // derived from DEX unless a monster override
  'speed',              // legacy scalar; `speeds` is the real input
  'extraAttacks',       // resolveMulticlassProgression
  'carriedWeight', 'attunementCount', 'spellSaveDc', 'spellAttackBonus',
]);
// --- COSMETIC: free text and appearance, always player-writable ---------------
const COSMETIC_FIELDS = new Set([
  'name', 'color', 'imageUrl', 'playerName', 'playerDescription', 'notes',
  'alignment', 'traits_text', 'ideals', 'bonds', 'flaws', 'backstory',
  'faction', 'role', 'darkvision', 'lightRadius', 'tempEffects',
  'features', 'proficiencies', 'attacks', 'spells', 'xp',
]);

function fieldCategory(field) {
  if (field in LIVE_FIELDS) return FIELD_CATEGORY.LIVE;
  if (DERIVED_FIELDS.has(field)) return FIELD_CATEGORY.DERIVED;
  if (DM_FIELDS.has(field)) return FIELD_CATEGORY.DM;
  if (BUILD_FIELDS.has(field)) return FIELD_CATEGORY.BUILD;
  if (COSMETIC_FIELDS.has(field)) return FIELD_CATEGORY.COSMETIC;
  return null;                                   // unknown: refused by default
}

// --- Campaign permissions -----------------------------------------------------
// What a table allows its players to do. Conservative defaults: a player may
// build their own character but may not touch DM authority or derived stats.
const PLAYER_PERMISSIONS_DEFAULT = {
  buildEditing: true,        // may a player edit their own build at all?
  levelUp: 'request',        // 'allow' | 'request' | 'deny'
  abilityScores: 'request',  // ability scores are contentious; default to asking
  multiclass: 'request',
  spellPreparation: 'allow',
  inventory: 'allow',
  derivedOverrides: false,   // may a player override a DERIVED stat? almost never
  dmDelegated: [],           // explicit DM fields delegated to players
};
// The build areas a GM can set independently, in the order the settings panel
// shows them. Each is 'allow' | 'request' | 'deny', so a table can let players
// manage their own gear while still approving a level-up.
const PLAYER_PERM_LABELS = {
  abilityScores: 'Ability scores',
  levelUp: 'Levelling up',
  multiclass: 'Classes and subclasses',
  spellPreparation: 'Preparing spells',
  inventory: 'Inventory and gear',
};
const PLAYER_PERM_MODES = [
  ['allow', 'Free', 'players change this themselves'],
  ['request', 'Ask', 'the change is sent to you for approval'],
  ['deny', 'Locked', 'only you can change it'],
];
function playerPermissions(state) {
  return { ...PLAYER_PERMISSIONS_DEFAULT, ...(state?.playerPermissions || {}) };
}

// --- THE authority decision ---------------------------------------------------
// One function answers "may this player write this field, and if not, why?".
// Every write path consults it; the UI consults it too, so a control is
// rendered read-only for exactly the reason a write would be refused. That
// symmetry is the point - there should be no control that looks editable and
// then silently fails.
//
// ctx: { isDM, sheetMode: 'play'|'edit', owns, state }
function canPlayerWriteField(field, ctx = {}) {
  const allow = (category) => ({ ok: true, category, reason: null, action: null });
  const deny = (category, reason, action = null) => ({ ok: false, category, reason, action });
  const cat = fieldCategory(field);
  const perms = playerPermissions(ctx.state);

  if (cat === null) return deny(null, `"${field}" is not a recognised field`);
  // the DM may write anything except a derived value, which would be lost
  if (ctx.isDM) {
    return cat === FIELD_CATEGORY.DERIVED
      ? deny(cat, `${field} is computed from other values; set its inputs instead`)
      : allow(cat);
  }
  if (!ctx.owns) return deny(cat, 'you do not control this creature');

  switch (cat) {
    case FIELD_CATEGORY.COSMETIC:
      return allow(cat);
    case FIELD_CATEGORY.LIVE:
      // legal, but not through a generic patch
      return deny(cat, `${field} changes through play, not by editing`, LIVE_FIELDS[field]);
    case FIELD_CATEGORY.DERIVED:
      return perms.derivedOverrides
        ? allow(cat)
        : deny(cat, `${field} is calculated from your character sheet and cannot be set directly`);
    case FIELD_CATEGORY.DM:
      return (perms.dmDelegated || []).includes(field)
        ? allow(cat)
        : deny(cat, `${field} is set by the GM`);
    case FIELD_CATEGORY.BUILD: {
      if (!perms.buildEditing) return deny(cat, 'this campaign locks character builds');
      if (ctx.sheetMode !== 'edit') return deny(cat, `switch the sheet to edit mode to change ${field}`);
      // some build areas have their own campaign policy
      const gate = (mode, label) => mode === 'allow' ? allow(cat)
        : mode === 'request' ? deny(cat, `${label} needs GM approval`, 'submit_request')
        : deny(cat, `${label} is not permitted in this campaign`);
      if (field === 'stats') return gate(perms.abilityScores, 'changing ability scores');
      if (field === 'level') return gate(perms.levelUp, 'levelling up');
      if (field === 'classes' || field === 'subclass') return gate(perms.multiclass, 'changing classes');
      if (field === 'preparedSpells' || field === 'spellbook') return gate(perms.spellPreparation, 'preparing spells');
      if (field === 'items' || field === 'inventory' || field === 'money') return gate(perms.inventory, 'changing inventory');
      return allow(cat);
    }
    default:
      return deny(cat, 'not permitted');
  }
}
// Filter a patch to what this player may actually write, reporting the rest.
// The refusals carry their reason, so the host can tell the client WHY rather
// than dropping fields silently - which is what the old whitelist did.
function filterPlayerPatch(patch, ctx = {}) {
  const allowed = {}, refused = [];
  for (const [k, v] of Object.entries(patch || {})) {
    const verdict = canPlayerWriteField(k, ctx);
    if (verdict.ok) allowed[k] = v;
    else refused.push({ field: k, ...verdict });
  }
  return { allowed, refused, anyRefused: refused.length > 0 };
}
// ============================================================================
// SHEET MODES AND THE DRAFT CHANGE SET (v9.58)
// ============================================================================
// `sheetMode` and `canPlayerWriteField` existed; the sheet used neither. v9.57
// papered over that with a hidden `sheetEditMode` constant pinned to `true`,
// which is worse than not having modes at all: every build field was writable
// with no switch to turn that off.
//
// A DRAFT is the second half. Sending every keystroke meant a name change was
// twenty round trips, each one a chance for the host to answer out of order.
const SHEET_MODES = ['play', 'edit'];
function makeSheetDraft(entityId, baseline = {}) {
  return { entityId, changes: {}, baseline: { ...baseline }, requests: {}, ts: Date.now() };
}
// Stage one field. Nothing crosses the network until the draft is submitted.
function draftSet(draft, field, value) {
  if (!draft) return draft;
  const changes = { ...draft.changes, [field]: value };
  // setting a field back to its original value is not a change
  if (JSON.stringify(value) === JSON.stringify(draft.baseline?.[field])) delete changes[field];
  return { ...draft, changes };
}
function draftClear(draft, field) {
  if (!draft) return draft;
  const changes = { ...draft.changes };
  delete changes[field];
  return { ...draft, changes };
}
// v9.71: the entity AS THE PLAYER HAS EDITED IT. Editable controls must render
// from this, not from the authoritative entity: a control that reads live state
// computes its next change from a spellbook that does not include the change
// before it, so adding a second spell REPLACED the first.
//
// Only staged fields are projected, so a field nobody has touched still reads
// through to the authoritative value and a later GM edit to it is still seen.
function draftProjectedEntity(entity, draft, sheetMode = 'edit') {
  if (!entity) return entity;
  if (sheetMode !== 'edit' || !draft || !draftIsDirty(draft)) return entity;
  return { ...entity, ...draft.changes };
}
// The baseline a draft should carry AFTER a successful submission: the values
// the player just sent, not the ones that existed before they sent them.
// Rebasing on the pre-submit entity made the authoritative echo of the player's
// OWN change look like somebody else's edit.
function draftRebasedAfterSubmit(draft, entity, submitted = {}) {
  const base = { ...(entity || {}), ...(draft?.baseline || {}), ...submitted };
  return makeSheetDraft(draft?.entityId || entity?.id, base);
}
function draftIsDirty(draft) { return Object.keys(draft?.changes || {}).length > 0; }
function draftFieldCount(draft) { return Object.keys(draft?.changes || {}).length; }

// Split a draft into what can be applied, what needs asking, and what cannot
// happen at all - using the SAME permission function the host will use, so the
// UI never offers a control whose write is destined to be refused.
function partitionDraft(draft, ctx = {}) {
  const direct = {}, requests = [], denied = [];
  for (const [field, value] of Object.entries(draft?.changes || {})) {
    const v = canPlayerWriteField(field, ctx);
    if (v.ok) direct[field] = value;
    else if (v.action === 'submit_request') {
      requests.push({ field, value, reason: v.reason });
    } else {
      denied.push({ field, value, reason: v.reason, action: v.action || null });
    }
  }
  return {
    direct, requests, denied,
    anyDirect: Object.keys(direct).length > 0,
    anyRequests: requests.length > 0,
    anyDenied: denied.length > 0,
  };
}
// What submitting this draft will actually do, in words, BEFORE it is sent.
function draftSubmissionPlan(draft, ctx = {}) {
  const p = partitionDraft(draft, ctx);
  const lines = [];
  if (p.anyDirect) lines.push(`${Object.keys(p.direct).length} change(s) applied straight away`);
  if (p.anyRequests) lines.push(`${p.requests.length} sent to the GM for approval`);
  if (p.anyDenied) lines.push(`${p.denied.length} cannot be changed here`);
  return { ...p, summary: lines.join('; ') || 'nothing to submit',
    canSubmit: p.anyDirect || p.anyRequests };
}
// v9.58: a DM edit landing while a player holds a draft. The draft's baseline
// is what the field looked like when editing began; if the live value has moved
// since, the two are in conflict and the player must be told rather than having
// their stale value silently win.
function draftConflicts(draft, liveEntity) {
  const out = [];
  for (const field of Object.keys(draft?.changes || {})) {
    const was = draft.baseline?.[field];
    const now = liveEntity?.[field];
    if (JSON.stringify(was) === JSON.stringify(now)) continue;
    out.push({ field, yours: draft.changes[field], theirs: now, wasWhenYouStarted: was });
  }
  return out;
}
// Resolving one: keep yours, or take theirs and drop your edit.
function resolveDraftConflict(draft, field, choice, liveEntity) {
  if (choice === 'theirs') {
    const d = draftClear(draft, field);
    return { ...d, baseline: { ...d.baseline, [field]: liveEntity?.[field] } };
  }
  // keeping yours re-bases, so the same conflict is not reported twice
  return { ...draft, baseline: { ...draft.baseline, [field]: liveEntity?.[field] } };
}

// Is this control editable for this viewer? The UI asks the SAME function the
