  const target = state?.entities?.[targetId];
  if (!spec || !attacker || !target) return null;
  const elig = contestEligibility(state, { attackerId, targetId, kind });

  const attackerSkill = kind === 'escape' ? 'Athletics' : spec.attackerSkill;
