  const at = Object.values(state.tokens || {}).find(t => t.entityId === attackerId && t.mapId === state.currentMapId);
  const tt = Object.values(state.tokens || {}).find(t => t.entityId === targetId && t.mapId === state.currentMapId);
  if (!at || !tt) return { ok: false, reason: 'both creatures must be on the map' };
  const dx = tt.x - at.x, dy = tt.y - at.y;
