  const scaled = castLevel != null ? scaleSpell(spell, { slotLevel: castLevel }) : spell;
  const type = scaled.targetType || 'creature';
  const declared = Number(scaled.targets);
  const area = scaled.area && scaled.area.shape && scaled.area.shape !== 'none' && Number(scaled.area.size) > 0;

