  // `rotatable` too, so removing this changes nothing. Kept for the early exit.
  if (!spec?.rotatable) return placement;
  const casterTok = Object.values(state?.tokens || {})
    .find(t => t.entityId === placement.casterId && t.mapId === state.currentMapId);
  if (!casterTok || !point) return placement;
