  const pool = pools.find(p => p.sides === sides && (Number(p.max) || 0) - (Number(p.spent) || 0) > 0);
  if (!pool) return { entity, result: { ok: false, reason: 'no dice remaining', sides } };
  const r = Number.isFinite(roll) ? roll : (1 + Math.floor(Math.random() * sides));
  const conMod = abilityMod(effectiveStat(entity, 'con'));
  const heal = Math.max(0, r + conMod); // minimum 0 healing per die
  pool.spent = (Number(pool.spent) || 0) + 1;
  const withPools = { ...entity, hitDicePools: pools };
  const { entity: healed, result: hp } = applyHpTransaction(withPools, { delta: heal, source: 'hit die' });
